                offsets = [(w, 0), (0, -h), (0, h)]
                if w == 1 or h == 1:
                    offsets += [(w, -h), (w, h)]
            elif final_dir == 'up':
                offsets = [(0, -h), (-w, 0), (w, 0)]
                if w == 1 or h == 1:
                    offsets += [(-w, -h), (w, -h)]
            elif final_dir == 'down':
                offsets = [(0, h), (-w, 0), (w, 0)]
                if w == 1 or h == 1:
